mapper.select:
/* selectSellerMpIvPrewarhsngDeliveryManageList */ SELECT C.BUYER , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE=F_GET_HIDDEN_BUYER_NAME(C.BUYER, '01')) AS BUYER_NAME , A.BEFORE_GR_DATE , C.INV_NO , C.INV_AMT , COUNT(*) AS PRODUCT_CNT , A.REQ_USER_ID AS PURCHASER_ID , A.REQ_USER_NAME AS PURCHASER_NAME , A.REQ_USER_DEPT_CODE AS PURCHASER_DEPT , ( SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = C.BUYER AND CODE = A.REQ_USER_DEPT_CODE AND TYPE = 'C001' ) AS PURCHASER_DEPT_NAME , CASE DELIVERY_FLAG WHEN 'Y' THEN '납품완료' WHEN 'P' THEN '납품예정(협력사출력)' WHEN 'I' THEN '송장생성(운영사생성)' WHEN 'N' THEN '선입고요청' ELSE NULL END DELIVERY_STATUS , A.DELY_TO_LOCATION , A.BS_NO FROM KEP_BEFORE_STOCKED_MNG A , KEP_BEFORE_STOCKED_IVDT B , KEP_BEFORE_STOCKED_IVHD C WHERE A.BUYER = B.BUYER AND A.BS_NO = B.BS_NO AND B.SELLER = C.SELLER AND B.INV_NO = C.INV_NO AND B.BUYER = C.BUYER AND A.BEFORE_GR_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND A.AGENT_CODE = #{st_com_code} AND A.STATUS <> 'D'
AND A.BS_NO = #{st_bs_no}
AND A.BUYER = #{st_buyer_code}
GROUP BY C.BUYER , A.BEFORE_GR_DATE , C.INV_NO , C.INV_AMT , A.REQ_USER_ID , A.REQ_USER_NAME , A.REQ_USER_DEPT_CODE , A.DELY_TO_LOCATION , A.DELIVERY_FLAG , A.BS_NO ORDER BY INV_NO DESC
